{
  "items": [
    {
      "path": "tools.github.get_copilot_job_status",
      "description": "Get the status of a GitHub Copilot coding agent job. Use this to check if a previously submitted task has completed and to get the pull request URL once it's created. Provide the job ID (from create_pull_request_with_copilot) or pull request number (from assign_copilot_to_issue), or any pull request you want agent sessions for.",
      "signature": "tools.github.get_copilot_job_status({
  /** Job ID or pull request number */
  id: string,
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.render.list_log_label_values",
      "description": "List all values for a given log label in the logs matching the provided filters. This can be used to discover what values are available for filtering logs using the list_logs tool. You can query for logs across multiple resources, but all resources must be in the same region and belong to the same owner.",
      "signature": "tools.render.list_log_label_values({
  /**
   * The direction to query logs for. Backward will return most recent logs first. Forward will start with the oldest logs in the time range.
   * @default "backward"
   */
  direction?: "backward" | "forward",
  /**
   * End time for log query (RFC3339 format). Defaults to the current time. The end time must be within the last 30 days.
   */
  endTime?: string,
  /** Filter request logs by their host. Wildcards and regex are supported. */
  host?: Array<string>,
  /** Filter logs by the instance they were emitted from. */
  instance?: Array<string>,
  /** The label to list values for. */
  label: "host" | "instance" | "level" | "method" | "statusCode" | "type",
  /** Filter logs by their severity level. Wildcards and regex are supported. */
  level?: Array<string>,
  /** Filter request logs by their requests method. Wildcards and regex are supported. */
  method?: Array<string>,
  /** Filter request logs by their path. Wildcards and regex are supported. */
  path?: Array<string>,
  /** Filter by resource. A resource is the id of a server, cronjob, job, postgres, or redis. */
  resource: Array<string>,
  /**
   * Start time for log query (RFC3339 format). Defaults to 1 hour ago. The start time must be within the last 30 days.
   */
  startTime?: string,
  /** Filter request logs by their status code. Wildcards and regex are supported. */
  statusCode?: Array<string>,
  /** Filter by the text of the logs. Wildcards and regex are supported. */
  text?: Array<string>,
  /** Filter logs by their type. */
  type?: Array<string>,
  /** The ID of the Render workspace to use. Reuse the workspaceId the user confirmed from list_workspaces. */
  workspaceId?: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.notion["notion-get-session-status"]",
      "description": "Get the latest turn's status for a Custom Agent session without waiting.

Requires Notion AI and Custom Agents access. Call this tool directly. If access is denied, follow the recovery guidance in the result.",
      "signature": "tools.notion["notion-get-session-status"]({
  /**
   * Use the complete session_url returned by session tools, unchanged. Format: session://<spaceId>/<sessionId>. Shorthand session://<sessionId> and thread://<sessionId> use the connected workspace. Fully qualified URLs must refer to that workspace.
   * @minLength 1
   */
  session_url: string,
  /** Notion setup instructions version, such as 0.0.2. Omit if unknown. */
  instructions_version?: string,
  /**
   * For tracking only: the name of the agent skill you are following for this task, such as notion-meeting-prep. Omit if you are not following a skill.
   */
  skill?: string,
  [key: string]: unknown,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.pull_request_read",
      "description": "Get information on a specific pull request in GitHub repository.",
      "signature": "tools.github.pull_request_read({
  /**
   * Cursor for pagination, used only by the get_review_comments method. Pass the endCursor from the previous page's PageInfo to fetch the next page.
   */
  after?: string,
  /**
   * Action to specify what pull request data needs to be retrieved from GitHub.
   * Possible options:
   *  1. get - Get details of a specific pull request.
   *  2. get_diff - Get the diff of a pull request.
   *  3. get_status - Get combined commit status of a head commit in a pull request.
   *  4. get_files - Get the list of files changed in a pull request. Use with pagination parameters to control the number of results returned.
   *  5. get_commits - Get the list of commits on a pull request. Use with pagination parameters to control the number of results returned.
   *  6. get_review_comments - Get review threads on a pull request. Each thread contains logically grouped review comments made on the same code location during pull request reviews. Returns thread metadata and comments with nullable current and original line-range coordinates (line, start_line, original_line, original_start_line). Current coordinates are omitted when unavailable, such as for outdated comments. Use cursor-based pagination (perPage, after) to control results.
   *  7. get_reviews - Get the reviews on a pull request. When asked for review comments, use get_review_comments method. Use with pagination parameters to control the number of results returned.
   *  8. get_comments - Get comments on a pull request. Use this if user doesn't specifically want review comments. Use with pagination parameters to control the number of results returned.
   *  9. get_check_runs - Get check runs for the head commit of a pull request. Check runs are the individual CI/CD jobs and checks that run on the PR.
   */
  method: "get" | "get_diff" | "get_status" | "get_files" | "get_commits" | "get_review_comments" | "get_reviews" | "get_comments" | "get_check_runs",
  /** Repository owner */
  owner: string,
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /** Pull request number */
  pullNumber: number,
  /** Repository name */
  repo: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.run_secret_scanning",
      "description": "Scan files, content, or recent changes for secrets such as API keys, passwords, tokens, and credentials.

This tool is intended for targeted scans of specific files, snippets, or diffs provided directly as content. The files parameter accepts either a single string or an array of strings containing raw file contents or diff hunks, and returns detected secrets with their locations and related secret scanning metadata. Content must not be empty. For full repository scanning, other mechanisms are available.

Caveats:

- Only files within the codebase should be scanned. Files outside of the codebase should not be sent.
- Files listed in .gitignore should be skipped.",
      "signature": "tools.github.run_secret_scanning({
  /**
   * A single string or an array of strings containing file contents, snippets, or diff hunks to scan for secrets. These must be raw contents, not repository file paths.
   */
  files: string | Array<string>,
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.get_commit",
      "description": "Get details for a commit from a GitHub repository",
      "signature": "tools.github.get_commit({
  /**
   * Level of detail to include for changed files. "none" omits stats and files entirely. "stats" (default) includes per-file metadata: filename, status, and lines-of-code counts (additions, deletions, changes), with no patch content. "full_patch" additionally includes the unified diff content for each file and can be very large.
   * @default "stats"
   */
  detail?: "none" | "stats" | "full_patch",
  /** Repository owner */
  owner: string,
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /** Repository name */
  repo: string,
  /** Commit SHA, branch name, or tag name */
  sha: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.notion["notion-create-database"]",
      "description": "Creates a new Notion database using SQL DDL syntax, or a canonical typed database for tasks, projects, or skills.

Provide exactly one of:
- schema: a CREATE TABLE statement. If no title property is provided, "Name" is auto-added.
- database_type: one of tasks, projects, or skills. The database is created with the canonical required properties and typed metadata used by Notion.


For schema, use CREATE TABLE with double-quoted column names and single-quoted type options. If no title property is provided, "Name" is auto-added.

Property type syntax:
- Simple: TITLE, RICH_TEXT, DATE, PEOPLE, CHECKBOX, URL, EMAIL, PHONE_NUMBER, FILES
- SELECT('opt':color, ...) / MULTI_SELECT('opt':color, ...)
- Option names can't contain commas: use '$1000+', not '$1,000+'. List separate options as 'A', 'B', not 'A, B'.
- STATUS('Backlog':gray:to_do, 'Building':blue:in_progress, 'Shipped':green:complete); groups are to_do, in_progress, complete
- NUMBER [FORMAT 'dollar'] / FORMULA('expression')
- RELATION('ds') for a one-way relation
- RELATION('ds', DUAL) for a two-way relation
- RELATION('ds', DUAL 'Children') with a synced property name
- RELATION('ds', DUAL 'Children' 'children') with a synced name and synced_id (for self-relations)
- ROLLUP('rel_prop', 'target_prop', 'function')
- UNIQUE_ID [PREFIX 'WEB-BUG'] / CREATED_TIME / LAST_EDITED_TIME
- UNIQUE_ID PREFIX: 2-10 characters, a letter then letters, digits, or hyphens (e.g. 'TASK-ID', not 'TASK_ID' or 'T'). Each prefix can be used by only one data source per workspace, so prefer a specific prefix like 'WEB-BUG' over 'TASK'.
- Any column: COMMENT 'description text' Colors: default, gray, brown, orange, yellow, green, blue, purple, pink, red.


Returns Markdown with schema, SQLite definition, and data source ID in <data-source> tag for use with update_data_source and query_data_sources tools.",
      "signature": "tools.notion["notion-create-database"]({
  /**
   * The parent under which to create the new database. If omitted, the database will be created as a private page at the workspace level.
   */
  parent?: {
    /** The ID of the parent page, with or without dashes. */
    page_id: string,
    /** Always `page_id` */
    type?: "page_id",
    [key: string]: unknown,
  },
  /** The title of the new database. */
  title?: string,
  /** The description of the new database. */
  description?: string,
  /**
   * SQL DDL CREATE TABLE statement defining the database schema. Cannot be combined with database_type. Column names must be double-quoted and type options use single quotes.
   *
   * Property type syntax:
   * - Simple: TITLE, RICH_TEXT, DATE, PEOPLE, CHECKBOX, URL, EMAIL, PHONE_NUMBER, FILES
   * - SELECT('opt':color, ...) / MULTI_SELECT('opt':color, ...)
   * - Option names can't contain commas: use '$1000+', not '$1,000+'. List separate options as 'A', 'B', not 'A, B'.
   * - STATUS('Backlog':gray:to_do, 'Building':blue:in_progress, 'Shipped':green:complete); groups are to_do, in_progress, complete
   * - NUMBER [FORMAT 'dollar'] / FORMULA('expression')
   * - RELATION('ds') for a one-way relation
   * - RELATION('ds', DUAL) for a two-way relation
   * - RELATION('ds', DUAL 'Children') with a synced property name
   * - RELATION('ds', DUAL 'Children' 'children') with a synced name and synced_id (for self-relations)
   * - ROLLUP('rel_prop', 'target_prop', 'function')
   * - UNIQUE_ID [PREFIX 'WEB-BUG'] / CREATED_TIME / LAST_EDITED_TIME
   * - UNIQUE_ID PREFIX: 2-10 characters, a letter then letters, digits, or hyphens (e.g. 'TASK-ID', not 'TASK_ID' or 'T'). Each prefix can be used by only one data source per workspace, so prefer a specific prefix like 'WEB-BUG' over 'TASK'.
   * - Any column: COMMENT 'description text' Colors: default, gray, brown, orange, yellow, green, blue, purple, pink, red.
   *
   *
   * Examples:
   * - Minimal: <example>CREATE TABLE ("Name" TITLE)</example>
   * - With options: <example>CREATE TABLE ("Name" TITLE, "Budget" NUMBER FORMAT 'dollar', "Tags" MULTI_SELECT('eng':blue, 'design':pink), "Task ID" UNIQUE_ID PREFIX 'PRJ')</example>
   * - Self-relations are a two-step flow: create the database, then use its data source ID with update_data_source to add paired properties such as RELATION('ds', DUAL 'Children' 'children').
   */
  schema?: string,
  /**
   * Create a canonical typed database with Notion's required properties and metadata. Supported types: tasks, projects, skills. Example: <example>tasks</example>. Use title "Tasks" when needed.
   */
  database_type?: "tasks" | "projects" | "skills",
  /** Notion setup instructions version, such as 0.0.2. Omit if unknown. */
  instructions_version?: string,
  /**
   * For tracking only: the name of the agent skill you are following for this task, such as notion-meeting-prep. Omit if you are not following a skill.
   */
  skill?: string,
  [key: string]: unknown,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.search_issues",
      "description": "Search issues using natural-language semantic matching. Best for conceptual or paraphrased queries (e.g. "login fails after password reset"). Already scoped to is:issue.",
      "signature": "tools.github.search_issues({
  /**
   * Subset of fields to return for each issue result. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'body', 'reactions', and 'labels' in particular drops the largest per-result data.
   */
  fields?: Array<"number" | "title" | "body" | "state" | "state_reason" | "draft" | "locked" | "html_url" | "user" | "author_association" | "labels" | "assignee" | "assignees" | "milestone" | "comments" | "reactions" | "created_at" | "updated_at" | "closed_at" | "closed_by" | "type" | "repository_url" | "pull_request" | "field_values">,
  /** Sort order */
  order?: "asc" | "desc",
  /** Optional repository owner. If provided with repo, only issues for this repository are listed. */
  owner?: string,
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /**
   * The search query, as natural language. When the user gives alternative wordings, include them as plain words rather than joining them with OR.
   */
  query: string,
  /** Optional repository name. If provided with owner, only issues for this repository are listed. */
  repo?: string,
  /** Sort field by number of matches of categories, defaults to best match */
  sort?: "comments" | "reactions" | "reactions-+1" | "reactions--1" | "reactions-smile" | "reactions-thinking_face" | "reactions-heart" | "reactions-tada" | "interactions" | "created" | "updated",
}): Promise<unknown>"
    },
    {
      "path": "tools.render.list_logs",
      "description": "List logs matching the provided filters. Logs are paginated by start and end timestamps. There are more logs to fetch if hasMore is true in the response. Provide the nextStartTime and nextEndTime timestamps as the startTime and endTime query parameters to fetch the next page of logs. You can query for logs across multiple resources, but all resources must be in the same region and belong to the same owner.",
      "signature": "tools.render.list_logs({
  /**
   * The direction to query logs for. Backward will return most recent logs first. Forward will start with the oldest logs in the time range.
   * @default "backward"
   */
  direction?: "backward" | "forward",
  /**
   * End time for log query (RFC3339 format). Defaults to the current time. The end time must be within the last 30 days.
   */
  endTime?: string,
  /** Filter request logs by their host. Wildcards and regex are supported. */
  host?: Array<string>,
  /** Filter logs by the instance they were emitted from. An instance is the id of a specific running server. */
  instance?: Array<string>,
  /** Filter logs by their severity level. Wildcards and regex are supported. */
  level?: Array<string>,
  /** Maximum number of logs to return. @minimum 1 @maximum 100 */
  limit?: number,
  /** Filter request logs by their requests method. Wildcards and regex are supported. */
  method?: Array<string>,
  /** Filter request logs by their path. Wildcards and regex are supported. */
  path?: Array<string>,
  /** Filter logs by their resource. A resource is the id of a server, cronjob, job, postgres, redis, or workflow. */
  resource: Array<string>,
  /**
   * Start time for log query (RFC3339 format). Defaults to 1 hour ago. The start time must be within the last 30 days.
   */
  startTime?: string,
  /** Filter request logs by their status code. Wildcards and regex are supported. */
  statusCode?: Array<string>,
  /** Filter workflow logs by task or flow ID. Requires the workflow ID in resource. */
  task?: Array<string>,
  /**
   * Filter workflow logs by task run or flow run ID, for example the id start_flow_run returns. Requires the workflow ID in resource. Set startTime to before the run started: the default window is the last hour.
   */
  taskRun?: Array<string>,
  /** Filter by the text of the logs. Wildcards and regex are supported. */
  text?: Array<string>,
  /**
   * Filter logs by their type. Types include app for application logs, request for request logs, and build for build logs. You can find the full set of types available for a query by using the list_log_label_values tool.
   */
  type?: Array<string>,
  /** The ID of the Render workspace to use. Reuse the workspaceId the user confirmed from list_workspaces. */
  workspaceId?: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.browser.dialog",
      "description": "Inspect, accept, or dismiss an alert/confirm/prompt in this tab. No dialog is reported as null.",
      "signature": "tools.browser.dialog({
  /**
   * Exact tab ID returned by browser.tabs.open/list. Focus does not select a tool target.
   * @pattern ^tab_[a-f0-9-]{36}$
   */
  tabID: string,
  action: "get" | "accept" | "dismiss",
  /** @maxLength 2048 */
  promptText?: string,
}): Promise<{
  tab: {
    /** @pattern ^tab_[a-f0-9-]{36}$ */
    id: string,
    /** @maxLength 16384 */
    url: string,
    /** @maxLength 2048 */
    title: string,
    loading: boolean,
    /** @maxLength 2048 */
    loadError?: string,
    canGoBack: boolean,
    canGoForward: boolean,
    /** @integer @minimum 0 */
    generation: number,
  },
  dialog: {
      /** @maxLength 2048 */
      type: string,
      /** @maxLength 100000 */
      message: string,
      /** @maxLength 2048 */
      defaultValue: string,
    } | null,
}>"
    },
    {
      "path": "tools.github.add_issue_comment",
      "description": "Add a comment and/or reaction to a specific issue or issue comment in a GitHub repository. Use this tool with pull requests as well (in this case pass pull request number as issue_number), but only if user is not asking specifically to add or react to review comments. At least one of body or reaction is required.",
      "signature": "tools.github.add_issue_comment({
  /** Comment content. Required unless reaction is provided. @minLength 1 */
  body?: string,
  /**
   * The numeric ID of the issue or pull request comment to react to. Use this for reactions to comments; omit it to react to the issue or pull request itself. Cannot be combined with body.
   * @integer @minimum 1
   */
  comment_id?: number,
  /** Issue or pull request number to comment on or react to. */
  issue_number: number,
  /** Repository owner */
  owner: string,
  /** Emoji reaction to add. Required unless body is provided. */
  reaction?: "+1" | "-1" | "laugh" | "confused" | "heart" | "hooray" | "rocket" | "eyes",
  /** Repository name */
  repo: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.assign_copilot_to_issue",
      "description": "Assign Copilot to a specific issue in a GitHub repository.

This tool can help with the following outcomes:
- a Pull Request created with source code changes to resolve the issue


More information can be found at:
- https://docs.github.com/en/copilot/concepts/agents/cloud-agent/about-cloud-agent
",
      "signature": "tools.github.assign_copilot_to_issue({
  /**
   * Git reference (e.g., branch) that the agent will start its work from. If not specified, defaults to the repository's default branch
   */
  base_ref?: string,
  /**
   * Optional custom instructions to guide the agent beyond the issue body. Use this to provide additional context, constraints, or guidance that is not captured in the issue description
   */
  custom_instructions?: string,
  /** Issue number */
  issue_number: number,
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.create_branch",
      "description": "Create a new branch in a GitHub repository",
      "signature": "tools.github.create_branch({
  /** Name for new branch */
  branch: string,
  /** Source branch (defaults to repo default) */
  from_branch?: string,
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.create_or_update_file",
      "description": "Create or update a single file in a GitHub repository. 
If updating, you should provide the SHA of the file you want to update. Use this tool to create or update a file in a GitHub repository remotely; do not use it for local file operations.

To obtain the current blob SHA before updating, call the get_file_contents tool with the same owner, repo, and path, and set its ref parameter to this tool's branch value. The first text result reports the blob SHA for the requested path.

SHA MUST be provided for existing file updates.
",
      "signature": "tools.github.create_or_update_file({
  /** Set true to update a symbolic link itself; content must be its new target path. @default false */
  allow_symlink_write?: boolean,
  /** Branch to create/update the file in */
  branch: string,
  /**
   * Content of the file, exactly as it should appear once written. Do not base64-encode it; this server does that before calling the REST API.
   */
  content: string,
  /** Commit message */
  message: string,
  /** Repository owner (username or organization) */
  owner: string,
  /** Path where to create/update the file */
  path: string,
  /** Repository name */
  repo: string,
  /**
   * The blob SHA of the file being replaced. Required if the file already exists. Retrieve it with get_file_contents using the same owner, repo, and path, with ref set to this tool's branch value.
   */
  sha?: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.create_pull_request",
      "description": "Create a new pull request in a GitHub repository.",
      "signature": "tools.github.create_pull_request({
  /** Branch to merge into */
  base: string,
  /** PR description */
  body?: string,
  /** Create as draft PR */
  draft?: boolean,
  /** Branch containing changes */
  head: string,
  /** Allow maintainer edits */
  maintainer_can_modify?: boolean,
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
  /** GitHub usernames or ORG/team-slug team reviewers to request reviews from */
  reviewers?: Array<string>,
  /** PR title */
  title: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.create_pull_request_with_copilot",
      "description": "Delegate a task to GitHub Copilot coding agent to perform in the background. The agent will create a pull request with the implementation. You should use this tool if the user asks to create a pull request to perform a specific task, or if the user asks Copilot to do something.",
      "signature": "tools.github.create_pull_request_with_copilot({
  /**
   * Git reference (e.g., branch) that the agent will start its work from. If not specified, defaults to the repository's default branch
   */
  base_ref?: string,
  /** Repository owner. You can guess the owner, but confirm it with the user before proceeding. */
  owner: string,
  /** Detailed description of the task to be performed (e.g., 'Implement a feature that does X', 'Fix bug Y', etc.) */
  problem_statement: string,
  /** Repository name. You can guess the repository name, but confirm it with the user before proceeding. */
  repo: string,
  /** Title for the pull request that will be created */
  title: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.create_repository",
      "description": "Create a new GitHub repository in your account or specified organization",
      "signature": "tools.github.create_repository({
  /** Initialize with README */
  autoInit?: boolean,
  /** Repository description */
  description?: string,
  /** Repository name */
  name: string,
  /** Organization to create the repository in (omit to create in your personal account) */
  organization?: string,
  /** Whether the repository should be private. Defaults to true (private) when omitted. @default true */
  private?: boolean,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.delete_file",
      "description": "Delete a file from a GitHub repository",
      "signature": "tools.github.delete_file({
  /** Branch to delete the file from */
  branch: string,
  /** Commit message */
  message: string,
  /** Repository owner (username or organization) */
  owner: string,
  /** Path to the file to delete */
  path: string,
  /** Repository name */
  repo: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.fork_repository",
      "description": "Fork a GitHub repository to your account or specified organization",
      "signature": "tools.github.fork_repository({
  /** Organization to fork to */
  organization?: string,
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.get_file_contents",
      "description": "Get the contents of a file or directory from a GitHub repository",
      "signature": "tools.github.get_file_contents({
  /**
   * Subset of fields to return for each entry when the path is a directory. If omitted, all fields are returned. Ignored when the path is a single file. Use this to reduce response size when listing directories and you only need specific fields, e.g. just 'name' and 'type'.
   */
  fields?: Array<"type" | "name" | "path" | "size" | "sha" | "url" | "git_url" | "html_url" | "download_url">,
  /** Repository owner (username or organization) */
  owner: string,
  /** Path to file/directory. @default "/" */
  path?: string,
  /** Accepts optional git refs such as `refs/tags/{tag}`, `refs/heads/{branch}` or `refs/pull/{pr_number}/head` */
  ref?: string,
  /** Repository name */
  repo: string,
  /** Accepts optional commit SHA. If specified, it will be used instead of ref */
  sha?: string,
}): Promise<unknown>"
    }
  ],
  "remaining": 155,
  "next": {
    "offset": 20
  }
}

