    },
    {
      "path": "tools.github.run_secret_scanning",
      "description": "Scan files, content, or recent changes for secrets such as API keys, passwords, tokens, and credentials.

This tool is intended for targeted scans of specific files, snippets, or diffs provided directly as content. The files parameter accepts either a single string or an array of strings containing raw file contents or diff hunks, and returns detected secrets with their locations and related secret scanning metadata. Content must not be empty. For full repository scanning, other mechanisms are available.

Caveats:

- Only files within the codebase should be scanned. Files outside of the codebase should not be sent.
- Files listed in .gitignore should be skipped.",
      "signature": "tools.github.run_secret_scanning({
  /**
   * A single string or an array of strings containing file contents, snippets, or diff hunks to scan for secrets. These must be raw contents, not repository file paths.
   */
  files: string | Array<string>,
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
}): Promise<unknown>"
    },
    {
      "path": "tools.github.get_commit",
      "description": "Get details for a commit from a GitHub repository",
      "signature": "tools.github.get_commit({
  /**
   * Level of detail to include for changed files. "none" omits stats and files entirely. "stats" (default) includes per-file metadata: filename, status, and lines-of-code counts (additions, deletions, changes), with no patch content. "full_patch" additionally includes the unified diff content for each file and can be very large.
   * @default "stats"
   */
  detail?: "none" | "stats" | "full_patch",
  /** Repository owner */
  owner: string,
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
